    pre = [0] * (n + 1)
    for i in range(n):
        pre[i + 1] = pre[i] + a[i]
    res = []
    for k in range(n):
        # Takahashi's absorbed set is always a contiguous interval [l, r]
        # containing k; his size is the sum of that interval.
        # Explore every reachable interval by brute force.
        seen = {(k, k)}
        stack = [(k, k)]
        best = a[k]
        while stack:
            l, r = stack.pop()
            s = pre[r + 1] - pre[l]
            if s > best:
                best = s
            if l > 0 and a[l - 1] < s and (l - 1, r) not in seen:
                seen.add((l - 1, r))
                stack.append((l - 1, r))
            if r < n - 1 and a[r + 1] < s and (l, r + 1) not in seen:
                seen.add((l, r + 1))
                stack.append((l, r + 1))
        res.append(best)
    return ' '.join(map(str, res))
